-- Forward-only integrity guards discovered during the whole-codebase audit.

-- Immutable and append-only history can only be removed by the trusted
-- aggregate workspace-deletion path.
CREATE TRIGGER "document_versions_immutable_delete" BEFORE DELETE ON "document_versions" WHEN workspace_deletion_authorized() = 0 BEGIN SELECT RAISE(ABORT, 'immutable history cannot be deleted'); END;
CREATE TRIGGER "document_sections_immutable_delete" BEFORE DELETE ON "document_sections" WHEN workspace_deletion_authorized() = 0 BEGIN SELECT RAISE(ABORT, 'immutable history cannot be deleted'); END;
CREATE TRIGGER "generated_claims_immutable_delete" BEFORE DELETE ON "generated_claims" WHEN workspace_deletion_authorized() = 0 BEGIN SELECT RAISE(ABORT, 'immutable history cannot be deleted'); END;
CREATE TRIGGER "claim_evidence_immutable_delete" BEFORE DELETE ON "claim_evidence" WHEN workspace_deletion_authorized() = 0 BEGIN SELECT RAISE(ABORT, 'immutable history cannot be deleted'); END;
CREATE TRIGGER "job_posting_revisions_immutable_delete" BEFORE DELETE ON "job_posting_revisions" WHEN workspace_deletion_authorized() = 0 BEGIN SELECT RAISE(ABORT, 'immutable history cannot be deleted'); END;
CREATE TRIGGER "ats_reports_immutable_delete" BEFORE DELETE ON "ats_reports" WHEN workspace_deletion_authorized() = 0 BEGIN SELECT RAISE(ABORT, 'immutable history cannot be deleted'); END;
CREATE TRIGGER "ats_category_scores_immutable_delete" BEFORE DELETE ON "ats_category_scores" WHEN workspace_deletion_authorized() = 0 BEGIN SELECT RAISE(ABORT, 'immutable history cannot be deleted'); END;
CREATE TRIGGER "ats_findings_immutable_delete" BEFORE DELETE ON "ats_findings" WHEN workspace_deletion_authorized() = 0 BEGIN SELECT RAISE(ABORT, 'immutable history cannot be deleted'); END;

-- A document's readable head and all history links must stay in the same
-- document context.
CREATE TRIGGER "documents_current_version_context_insert" BEFORE INSERT ON "documents" WHEN NEW.current_version_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM document_versions v WHERE v.id=NEW.current_version_id AND v.workspace_id=NEW.workspace_id AND v.document_id=NEW.id) BEGIN SELECT RAISE(ABORT, 'document current version context mismatch'); END;
CREATE TRIGGER "documents_current_version_context_update" BEFORE UPDATE OF current_version_id ON "documents" WHEN NEW.current_version_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM document_versions v WHERE v.id=NEW.current_version_id AND v.workspace_id=NEW.workspace_id AND v.document_id=NEW.id) BEGIN SELECT RAISE(ABORT, 'document current version context mismatch'); END;
CREATE TRIGGER "document_versions_history_context_insert" BEFORE INSERT ON "document_versions" WHEN (NEW.parent_version_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM document_versions v WHERE v.id=NEW.parent_version_id AND v.workspace_id=NEW.workspace_id AND v.document_id=NEW.document_id)) OR (NEW.restored_from_version_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM document_versions v WHERE v.id=NEW.restored_from_version_id AND v.workspace_id=NEW.workspace_id AND v.document_id=NEW.document_id)) BEGIN SELECT RAISE(ABORT, 'document version history context mismatch'); END;

-- History and analysis rows cannot mix independent job/document contexts.
CREATE TRIGGER "job_posting_revisions_history_context_insert" BEFORE INSERT ON "job_posting_revisions" WHEN NEW.parent_revision_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM job_posting_revisions r WHERE r.id=NEW.parent_revision_id AND r.workspace_id=NEW.workspace_id AND r.job_posting_id=NEW.job_posting_id) BEGIN SELECT RAISE(ABORT, 'job revision history context mismatch'); END;
CREATE TRIGGER "job_requirement_sets_history_context_insert" BEFORE INSERT ON "job_requirement_sets" WHEN NEW.parent_set_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM job_requirement_sets s WHERE s.id=NEW.parent_set_id AND s.workspace_id=NEW.workspace_id AND s.job_posting_revision_id=NEW.job_posting_revision_id) BEGIN SELECT RAISE(ABORT, 'requirement set history context mismatch'); END;
CREATE TRIGGER "job_requirement_sets_history_context_update" BEFORE UPDATE OF parent_set_id,job_posting_revision_id ON "job_requirement_sets" WHEN NEW.parent_set_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM job_requirement_sets s WHERE s.id=NEW.parent_set_id AND s.workspace_id=NEW.workspace_id AND s.job_posting_revision_id=NEW.job_posting_revision_id) BEGIN SELECT RAISE(ABORT, 'requirement set history context mismatch'); END;
CREATE TRIGGER "extraction_proposals_batch_context_insert" BEFORE INSERT ON "extraction_proposals" WHEN NOT EXISTS (SELECT 1 FROM extraction_batches b WHERE b.id=NEW.batch_id AND b.workspace_id=NEW.workspace_id AND b.source_document_id=NEW.source_document_id AND b.target_career_entry_id IS NEW.target_career_entry_id) BEGIN SELECT RAISE(ABORT, 'extraction proposal batch context mismatch'); END;
CREATE TRIGGER "extraction_proposals_batch_context_update" BEFORE UPDATE OF batch_id,source_document_id,target_career_entry_id ON "extraction_proposals" WHEN NOT EXISTS (SELECT 1 FROM extraction_batches b WHERE b.id=NEW.batch_id AND b.workspace_id=NEW.workspace_id AND b.source_document_id=NEW.source_document_id AND b.target_career_entry_id IS NEW.target_career_entry_id) BEGIN SELECT RAISE(ABORT, 'extraction proposal batch context mismatch'); END;
CREATE TRIGGER "tailoring_runs_context_insert" BEFORE INSERT ON "tailoring_runs" WHEN NOT EXISTS (SELECT 1 FROM documents d JOIN document_versions v ON v.id=NEW.base_version_id AND v.workspace_id=NEW.workspace_id AND v.document_id=d.id WHERE d.id=NEW.document_id AND d.workspace_id=NEW.workspace_id AND d.kind=NEW.kind) OR NOT EXISTS (SELECT 1 FROM job_requirement_sets s WHERE s.id=NEW.requirement_set_id AND s.workspace_id=NEW.workspace_id AND s.job_posting_revision_id=NEW.job_posting_revision_id) OR NOT EXISTS (SELECT 1 FROM requirement_match_runs m WHERE m.id=NEW.match_run_id AND m.workspace_id=NEW.workspace_id AND m.requirement_set_id=NEW.requirement_set_id) BEGIN SELECT RAISE(ABORT, 'tailoring run context mismatch'); END;
CREATE TRIGGER "tailoring_runs_context_update" BEFORE UPDATE OF kind,document_id,base_version_id,job_posting_revision_id,requirement_set_id,match_run_id ON "tailoring_runs" WHEN NOT EXISTS (SELECT 1 FROM documents d JOIN document_versions v ON v.id=NEW.base_version_id AND v.workspace_id=NEW.workspace_id AND v.document_id=d.id WHERE d.id=NEW.document_id AND d.workspace_id=NEW.workspace_id AND d.kind=NEW.kind) OR NOT EXISTS (SELECT 1 FROM job_requirement_sets s WHERE s.id=NEW.requirement_set_id AND s.workspace_id=NEW.workspace_id AND s.job_posting_revision_id=NEW.job_posting_revision_id) OR NOT EXISTS (SELECT 1 FROM requirement_match_runs m WHERE m.id=NEW.match_run_id AND m.workspace_id=NEW.workspace_id AND m.requirement_set_id=NEW.requirement_set_id) BEGIN SELECT RAISE(ABORT, 'tailoring run context mismatch'); END;
CREATE TRIGGER "tailoring_gaps_requirement_context_insert" BEFORE INSERT ON "tailoring_gaps" WHEN NOT EXISTS (SELECT 1 FROM tailoring_runs r JOIN job_requirements q ON q.id=NEW.requirement_id AND q.workspace_id=NEW.workspace_id AND q.requirement_set_id=r.requirement_set_id WHERE r.id=NEW.run_id AND r.workspace_id=NEW.workspace_id) BEGIN SELECT RAISE(ABORT, 'tailoring gap requirement context mismatch'); END;
CREATE TRIGGER "tailoring_suggestion_requirements_context_insert" BEFORE INSERT ON "tailoring_suggestion_requirements" WHEN NOT EXISTS (SELECT 1 FROM tailoring_suggestions s JOIN tailoring_runs r ON r.id=s.run_id AND r.workspace_id=s.workspace_id JOIN job_requirements q ON q.id=NEW.requirement_id AND q.workspace_id=NEW.workspace_id AND q.requirement_set_id=r.requirement_set_id WHERE s.id=NEW.suggestion_id AND s.workspace_id=NEW.workspace_id) BEGIN SELECT RAISE(ABORT, 'tailoring suggestion requirement context mismatch'); END;
CREATE TRIGGER "tailoring_run_evidence_entry_context_insert" BEFORE INSERT ON "tailoring_run_evidence" WHEN NOT EXISTS (SELECT 1 FROM evidence_facts f JOIN tailoring_run_entries e ON e.run_id=NEW.run_id AND e.workspace_id=NEW.workspace_id AND e.career_entry_id=f.career_entry_id WHERE f.id=NEW.evidence_fact_id AND f.workspace_id=NEW.workspace_id) BEGIN SELECT RAISE(ABORT, 'tailoring evidence entry context mismatch'); END;
CREATE TRIGGER "tailoring_claim_evidence_run_context_insert" BEFORE INSERT ON "tailoring_claim_evidence" WHEN NOT EXISTS (SELECT 1 FROM tailoring_claim_candidates c JOIN tailoring_suggestions s ON s.id=c.suggestion_id AND s.workspace_id=c.workspace_id JOIN tailoring_run_evidence e ON e.run_id=s.run_id AND e.workspace_id=s.workspace_id AND e.evidence_fact_id=NEW.evidence_fact_id WHERE c.id=NEW.claim_candidate_id AND c.workspace_id=NEW.workspace_id) BEGIN SELECT RAISE(ABORT, 'tailoring claim evidence context mismatch'); END;
CREATE TRIGGER "ats_reports_context_insert" BEFORE INSERT ON "ats_reports" WHEN NOT EXISTS (SELECT 1 FROM document_versions v WHERE v.id=NEW.document_version_id AND v.workspace_id=NEW.workspace_id AND v.content_hash=NEW.document_hash) OR (NEW.requirement_set_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM job_requirement_sets s JOIN job_posting_revisions r ON r.id=NEW.job_posting_revision_id AND r.workspace_id=NEW.workspace_id AND r.content_hash=NEW.job_hash WHERE s.id=NEW.requirement_set_id AND s.workspace_id=NEW.workspace_id AND s.job_posting_revision_id=r.id)) BEGIN SELECT RAISE(ABORT, 'ATS report context mismatch'); END;

-- Storage-backed identifiers and keys must always be safe and canonical, even
-- for direct database writes and future maintenance code.
CREATE TRIGGER "source_documents_storage_key_insert" BEFORE INSERT ON "source_documents" WHEN NOT regexp('^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',NEW.id) OR NEW.storage_key <> NEW.workspace_id || '/' || NEW.id || '.bin' BEGIN SELECT RAISE(ABORT, 'invalid source storage identity'); END;
CREATE TRIGGER "source_documents_storage_key_update" BEFORE UPDATE OF id,workspace_id,storage_key ON "source_documents" WHEN NOT regexp('^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',NEW.id) OR NEW.storage_key <> NEW.workspace_id || '/' || NEW.id || '.bin' BEGIN SELECT RAISE(ABORT, 'invalid source storage identity'); END;
CREATE TRIGGER "export_artifacts_storage_key_insert" BEFORE INSERT ON "export_artifacts" WHEN NOT regexp('^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',NEW.id) OR NEW.storage_key <> NEW.workspace_id || '/' || NEW.id || '.bin' BEGIN SELECT RAISE(ABORT, 'invalid export storage identity'); END;

-- Once deletion is requested, every ordinary workspace-scoped mutation is
-- frozen. The trusted deletion connection bypasses these guards explicitly.
CREATE TRIGGER "career_profiles_frozen_delete" BEFORE DELETE ON "career_profiles" WHEN workspace_deletion_authorized() = 0 AND EXISTS (SELECT 1 FROM workspaces w WHERE w.id=OLD.workspace_id AND w.deletion_requested_at IS NOT NULL) BEGIN SELECT RAISE(ABORT, 'workspace pending deletion'); END;
